#include <iostream>
#include <vector>

int main() {
    using namespace std;
    int X, N;
    cin >> X >> N;
    vector<int> W(N);
    for (auto&& w : W)
        cin >> w;
    vector<bool> b(N); // b[i] := i 種類目のパーツがついていれば true, そうでなければ false

    int Q;
    cin >> Q;
    for (int q = 0; q < Q; ++q) {
        int P;
        cin >> P;
        --P;
        if (b[P]) { // すでについていたら
            b[P] = false; // 外す
        } else { // ついていなければ
            b[P] = true; // つける
        }

        // 重さを求める
        int weight = X;
        for (int i = 0; i < N; ++i) {
            if (b[i]) { // i 番目のパーツがついていれば
                weight += W[i]; // 重さを足す
            }
        }
        cout << weight << endl;
        // #include <numeric> して
        // cout << transform_reduce(begin(W), end(W), begin(b), X) << endl;
        // と書いてもいい
    }
    return 0;
}

