#include <iostream>
#include <vector>

int main() {
    using namespace std;
    int X, N;
    cin >> X >> N;
    vector<int> W(N);
    for (auto&& w : W)
        cin >> w;
    vector<bool> b(N); // b[i] := i 種類目のパーツがついていれば true, そうでなければ false
    int weight = X; // 現在の重さ

    int Q;
    cin >> Q;
    for (int q = 0; q < Q; ++q) {
        int P;
        cin >> P;
        --P;

        if (b[P]) { // すでについていたら
            b[P] = false; // 外して
            weight -= W[P]; // 重さも減らす
        } else { // ついていなければ
            b[P] = true; // つけて
            weight += W[P]; // 重さを増やす
        }

        cout << weight << endl;
    }
    return 0;
}
